// The operations client a board command runs with. The generator prepends
// this file to header.js and detail.js; observability/tests/recovery.test.ts
// imports it as a module through the export line, which the generator drops.

const LIQUIDITY_CLIENT = 'st0x-liquidity-client --env production';

// The board always knows its environment: the selector's text is production
// or staging.
const boardEnv = (envText) => (envText === 'staging' ? 'staging' : 'production');

const forClientEnv = (command, env) => command.replace('--env production', `--env ${env}`);

const clientFor = (envText) => forClientEnv(LIQUIDITY_CLIENT, boardEnv(envText));


// The header's input rows by their `k` column. The generator prepends this
// file to header.js; observability/tests/board-header.test.ts imports it as
// a module through the export line, which the generator drops.
//
// The stackdriver datasource runs a range query even for an instant target,
// so each `k` can arrive at several times. A plain value keeps its newest
// row. The commit and info series carry their sample timestamp as the
// value, because a restart or deploy leaves the previous label set in the
// lookback window at the same row times: the largest value is the label set
// the bot runs now. A row whose value is not a finite number carries no
// timestamp, so it never takes the newest slot.
const readHeaderRows = (rows) => {
  const value = {};
  const seen = {};
  const newest = {};
  for (const row of rows) {
    if (row.k === 'commit' || row.k === 'info') {
      const at = row.Value === null || row.Value === undefined || row.Value === '' ? NaN : Number(row.Value);
      if (!Number.isFinite(at)) continue;
      if (!newest[row.k] || at > newest[row.k].at) newest[row.k] = { row, at };
      continue;
    }
    const time = Number(row.Time) || 0;
    if (row.k in seen && seen[row.k] > time) continue;
    seen[row.k] = time;
    value[row.k] =
      row.Value === null || row.Value === undefined || Number.isNaN(Number(row.Value)) ? null : Number(row.Value);
  }
  return {
    value,
    commit: newest.commit ? { sha: newest.commit.row.git_commit, at: newest.commit.at } : null,
    info: newest.info ? newest.info.row : {},
  };
};

// Each symbol's wrapper ratio per chain, underlying shares per wrapped
// share, from the `wrapper_ratio` rows: { symbol: { chain: ratio } }, the
// newest row of each.
const readWrapperRatios = (rows) => {
  const ratios = {};
  const seen = {};
  for (const row of rows) {
    if (row.k !== 'wrapper_ratio' || !row.symbol || !row.chain) continue;
    const ratio = Number(row.Value);
    if (row.Value === null || row.Value === '' || !Number.isFinite(ratio) || ratio <= 0) continue;
    const key = `${row.symbol}/${row.chain}`;
    const time = Number(row.Time) || 0;
    if (key in seen && seen[key] > time) continue;
    seen[key] = time;
    (ratios[row.symbol] = ratios[row.symbol] || {})[row.chain] = ratio;
  }
  return ratios;
};


// The Copy button beside each recovery command in the header's guide and the
// row dialog. The generator prepends this file to header.js and detail.js;
// observability/tests/board-copy-command.test.ts imports it as a module
// through the export line, which the generator drops.

// The markup of one command: its text in a <pre> and the button that copies
// it. `commandHtml` is already escaped.
const commandLine = (commandHtml, preClass) =>
  `<div class="liq-command-line"><pre${preClass ? ` class="${preClass}"` : ''}>${commandHtml}</pre>` +
  '<button type="button" class="liq-copy" data-copy>Copy</button></div>';

// Wires every Copy button under `container` to its command. Property
// handlers, so a render that keeps the buttons replaces them instead of
// stacking another copy. The button says how the copy went for a moment.
const wireCopyButtons = (container) => {
  container.querySelectorAll('[data-copy]').forEach((button) => {
    button.onclick = () => {
      const command = button.parentElement.querySelector('pre').textContent;
      const show = (label) => {
        button.textContent = label;
        clearTimeout(button.liqCopyReset);
        button.liqCopyReset = setTimeout(() => {
          button.textContent = 'Copy';
        }, 1500);
      };
      if (!navigator.clipboard) {
        show('Copy failed');
        return;
      }
      navigator.clipboard.writeText(command).then(
        () => show('Copied'),
        () => show('Copy failed')
      );
    };
  });
};


// Behaviour the board's native tables cannot configure. The generator
// prepends this file to header.js, which installs it once per page;
// observability/tests/board-tables.test.ts imports it as a module through the
// export line, which the generator drops.
//
// - Hover text: a table cell's <abbr title> or <img title> shows its title
//   at once in a tooltip, instead of the browser's late, faint one. The
//   cell sanitizer keeps `title` on <abbr> and <img> only, so the board's
//   lights use <abbr> and its chain marks <img>.
// - Header hover: a column header named in `headerTips` for its panel
//   explains itself in the same tooltip.
// - Row hover: a cell's <abbr title="row:<key>"> in a panel named in
//   `rowTips` shows its row's flags as a table, read from the panel's data
//   in the dashboard scene: a symbol's every chain row, or one chain's. The
//   flags field packs one digit per column, and each column's `states`
//   names that digit's text, colour and light.
// - Chain tints: a row whose cell holds a chain's mark (an <img> whose alt
//   starts with a name in `rowTints`) takes that chain's tint. It shows
//   through a ratio bar's translucent track; the bar's fill is opaque, so
//   its red or green stays the verdict's.
// - Tree sort: clicking a column name sorts the table, and Grafana has no
//   option to turn that off. Tables whose rows are a tree (an asset row with
//   its chain rows under it) lose the tree on Grafana's sort, so a click on a
//   column name of a panel in `lockedSortPanels` never reaches it. A header
//   named in that panel's `treeSorts` sorts it instead, by a hidden key every
//   row of a group shares and then the row key, so each group stays whole:
//   largest first, then smallest first, then the default order again. The
//   first column restores the default order; another header does nothing.
//   The sort swaps the panel's sortBy transformations in the dashboard scene
//   (window.__grafanaSceneContext) and lives on the panel's data, so a
//   refresh keeps it. The filter button beside a name still works.
// - Plain hover: a cell with a tooltip field (the USD worth of a share
//   amount) opens it from a grey corner triangle only. The triangle is
//   stretched over the whole cell and made invisible, so the pointer
//   anywhere on the cell opens it.
// - Aligned edges: the tables in `alignedPanels` always keep room for a
//   scrollbar, so a table that scrolls ends its last column where one that
//   does not ends it, and their ratio bars line up.

const PANEL_TESTID = 'data-testid Panel header ';
const TOOLTIP_CARET = '[data-testid="data-testid tableng tooltip caret"]';
// An img keeps matching once its title moved to data-liq-tip, so the tip
// still hides when the pointer leaves it.
const TIP_CELL =
  '[role="gridcell"] abbr, [role="gridcell"] img[title], [role="gridcell"] img[data-liq-tip], [role="gridcell"][data-liq-unit]';
const ROW_TIP = 'row:';

// The rules and the listeners follow each render's code and options, so a
// board saved with new ones applies them without a page reload: each render
// removes the listeners the previous one added and adds its own.
// The panel titled `title` in the dashboard scene, if the scene has it.
const scenePanel = (doc, title) =>
  doc.liqSceneOf?.()?.state?.body?.state?.grid?.state?.children?.find(
    (child) => child.state.body?.state?.title === title
  )?.state.body;

const escapeTip = (text) =>
  String(text).replace(/[&<>"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[char]);

// A frame's field by its name or the display name a rename gave it.
const fieldNamed = (frame, names) =>
  frame?.fields?.find((field) =>
    names.some((name) => [field.name, field.config?.displayName, field.state?.displayName].includes(name))
  );

// The chain rows a row tip lists for `key`: a symbol's every chain, or the
// one chain of a symbol/chain key, as [chain name, flag digits]. A symbol
// lists its chains without flags too, digits null, so its tip is the asset's
// overview and never reads as one chain's.
const rowFlags = (doc, title, key) => {
  const config = doc.liqRowTips[title];
  const frame = scenePanel(doc, title)?.state?.$data?.state?.data?.series?.[0];
  const rows = fieldNamed(frame, config.rowFields);
  const flags = fieldNamed(frame, config.flagFields);
  if (!rows || !flags) return [];
  return rows.values.flatMap((row, index) => {
    const [symbol, chain] = String(row).split('/');
    const value = Number(flags.values[index]);
    const wanted = key.includes('/') ? String(row) === key : symbol === key;
    if (!wanted || !chain || !(chain in config.chains)) return [];
    const published = flags.values[index] != null && Number.isFinite(value);
    if (!published) return key.includes('/') ? [] : [[config.chains[chain], null]];
    return [[config.chains[chain], String(Math.round(value))]];
  });
};

// A row tip: its symbol (and chain), then one line per chain with a light
// and a word for each flag.
const rowTipHtml = (doc, title, key) => {
  const config = doc.liqRowTips[title];
  const [symbol, chain] = key.split('/');
  const heading = chain ? `${symbol} on ${config.chains[chain] ?? chain}` : symbol;
  const head = `<div class="liq-tip-title">${escapeTip(heading)}</div>`;
  const rows = rowFlags(doc, title, key);
  if (!rows.some(([, digits]) => digits)) return `${head}<div>${escapeTip(config.empty)}</div>`;
  const cell = (column, digit) => {
    const [text, color, light] = column.states[digit] ?? ['unknown', 'inherit', '?'];
    return `<td><span style="color:${escapeTip(color)}">${escapeTip(light)}</span> ${escapeTip(text)}</td>`;
  };
  const header = config.columns.map((column) => `<th>${escapeTip(column.name)}</th>`).join('');
  const lines = rows
    .map(([name, digits]) =>
      digits
        ? `<tr><th>${escapeTip(name)}</th>${config.columns.map((column, index) => cell(column, digits[index])).join('')}</tr>`
        : `<tr><th>${escapeTip(name)}</th><td colspan="${config.columns.length}">not published</td></tr>`
    )
    .join('');
  return `${head}<table><tr><th></th>${header}</tr>${lines}</table>`;
};

// The sorted header's arrow, from each tree table's sort on its data.
const drawSortArrows = (doc, panel) => {
  let style = doc.getElementById('liq-board-sort');
  if (!style) {
    style = doc.createElement('style');
    style.id = 'liq-board-sort';
    doc.head.appendChild(style);
  }
  style.textContent = Object.keys(doc.liqTreeSorts)
    .map((title) => [title, scenePanel(doc, title)?.state?.$data?.liqSort])
    .filter(([, sort]) => sort)
    .map(
      ([title, sort]) =>
        `${panel(title)} [role="columnheader"][aria-colindex="${sort.column}"] button:not([aria-label])::after` +
        // At the header cell's right edge (the cell is positioned; the name
        // button clips its own overflow), so the text keeps its room.
        `{content:"${sort.desc ? '\\25BC' : '\\25B2'}";position:absolute;right:4px;top:50%;` +
        'transform:translateY(-50%);font-size:9px;color:#6e9fff}'
    )
    .join('');
};

// A click on a tree table's header: the next sort in its cycle (largest
// first, smallest first, default), or the default order from the first
// column.
const treeSort = (doc, panel, title, header, column) => {
  const config = doc.liqTreeSorts[title];
  const data = scenePanel(doc, title)?.state?.$data;
  if (!config || !data?.reprocessTransformations) return;
  const key = config.keys[header];
  if (!key && column !== '1') return;
  data.liqDefault = data.liqDefault || data.state.transformations;
  const current = data.liqSort;
  const next = !key ? null : current?.key !== key ? { key, column, desc: true } : current.desc ? { key, column, desc: false } : null;
  const sortBy = (field, desc) => ({ id: 'sortBy', options: { fields: {}, sort: [{ field, desc }] } });
  let transformations = data.liqDefault;
  if (next) {
    // sortBy sorts stably and the last one applied leads: by the key, and
    // within a group (equal keys) by the row key, which puts the group's
    // head first.
    const rest = data.liqDefault.filter((step) => step.id !== 'sortBy');
    const at = rest.findIndex((step) => step.id === 'organize');
    transformations = [...rest.slice(0, at), sortBy(config.rowField, false), sortBy(key, next.desc), ...rest.slice(at)];
  }
  data.liqSort = next;
  data.setState({ transformations });
  data.reprocessTransformations();
  drawSortArrows(doc, panel);
};

// Unit tags: in a panel named in `unitTags`, a `column` cell gets the
// `text` of the first of its `tags` whose `values` hold its row's `match`
// cell, after its value (an onchain trade's size is in wrapped shares, a
// broker hedge's in underlying shares). On hover it shows the amount in the
// tag's `convert.unit`, through its row's `symbol` wrapper ratio on each
// chain (`wrapperRatios`, underlying shares per wrapped share): times the
// ratio, or divided by it. At today's ratio: the trade's own is not logged. Grafana redraws the table and
// reuses its row elements as it scrolls, so the tags follow every change to
// the panel's cells; tagging only sets attributes, which the observer does
// not watch, so it never feeds itself.
const formatShares = (value) => value.toLocaleString('en-US', { maximumFractionDigits: 3 });

// A number as Grafana's `locale` unit writes it, in the browser's own
// format: "1,020.5" in en-US, "1.020,5" in es-AR.
const parseLocaleNumber = (text) => {
  const parts = new Intl.NumberFormat().formatToParts(12345.6);
  const group = parts.find((part) => part.type === 'group')?.value ?? ',';
  const decimal = parts.find((part) => part.type === 'decimal')?.value ?? '.';
  return Number(text.trim().split(group).join('').split(decimal).join('.'));
};

// The hover text of a tagged `amount` of `symbol`.
const unitTip = (doc, tag, found, symbol, amount) => {
  const { unit, times } = found.convert;
  const ratios = Object.entries(doc.liqWrapperRatios?.[symbol] ?? {});
  if (!Number.isFinite(amount) || ratios.length === 0) {
    return `${found.tip} No wrapper ratio published for ${symbol} yet.`;
  }
  const converted = ratios.map(([chain, ratio]) => {
    const value = times ? amount * ratio : amount / ratio;
    const where = ratios.length > 1 ? ` on ${tag.chains?.[chain] ?? chain}` : '';
    return `${formatShares(value)} ${unit}${where}`;
  });
  return `${formatShares(amount)} ${found.text} ≈ ${converted.join(', ')} at today's wrapper ratio`;
};

const tagUnits = (doc, panel, unitTags) => {
  for (const observer of doc.liqUnitObservers ?? []) observer.disconnect();
  doc.liqUnitObservers = [];
  const Observer = doc.defaultView?.MutationObserver ?? globalThis.MutationObserver;
  for (const [title, tag] of Object.entries(unitTags)) {
    const section = doc.querySelector(panel(title));
    if (!section) continue;
    const apply = () => {
      const headers = [...section.querySelectorAll('[role="columnheader"]')];
      const index = (name) => headers.find((header) => header.textContent.trim() === name)?.getAttribute('aria-colindex');
      const from = index(tag.match);
      const to = index(tag.column);
      const symbolAt = index(tag.symbol);
      for (const row of section.querySelectorAll('[role="row"]')) {
        const cell = to ? row.querySelector(`[role="gridcell"][aria-colindex="${to}"]`) : null;
        if (!cell) continue;
        const source = from ? row.querySelector(`[role="gridcell"][aria-colindex="${from}"]`) : null;
        const found = source ? tag.tags.find(({ values }) => values.includes(source.textContent.trim())) : null;
        if (found) {
          const symbol = symbolAt
            ? (row.querySelector(`[role="gridcell"][aria-colindex="${symbolAt}"]`)?.textContent.trim() ?? '')
            : '';
          const amount = parseLocaleNumber(cell.textContent);
          cell.dataset.liqUnit = found.text;
          cell.dataset.liqTip = found.convert ? unitTip(doc, tag, found, symbol, amount) : found.tip;
        } else if (cell.dataset.liqUnit) {
          delete cell.dataset.liqUnit;
          delete cell.dataset.liqTip;
        }
      }
    };
    apply();
    if (!Observer) continue;
    const observer = new Observer(apply);
    observer.observe(section, { childList: true, subtree: true, characterData: true });
    doc.liqUnitObservers.push(observer);
  }
};

const installBoardTables = (
  doc,
  {
    lockedSortPanels,
    alignedPanels,
    rowTints = {},
    headerTips = {},
    treeSorts = {},
    rowTips = {},
    unitTags = {},
    wrapperRatios = {},
    sceneOf = () => doc.defaultView?.__grafanaSceneContext,
    theme,
  }
) => {
  doc.liqSceneOf = sceneOf;
  doc.liqWrapperRatios = wrapperRatios;
  const panel = (title) => `section[data-testid="${PANEL_TESTID}${title}"]`;
  doc.liqHeaderTips = headerTips;
  doc.liqTreeSorts = treeSorts;
  doc.liqRowTips = rowTips;
  doc.liqPanelSelector = panel;
  const locked = lockedSortPanels.map(panel);
  doc.liqLockedTables = locked;
  const aligned = alignedPanels.map((title) => `${panel(title)} [role="grid"]`);
  let style = doc.getElementById('liq-board-tables');
  if (!style) {
    style = doc.createElement('style');
    style.id = 'liq-board-tables';
    doc.head.appendChild(style);
  }
  style.textContent =
    '.liq-tip{position:fixed;z-index:10000;pointer-events:none;padding:4px 8px;' +
    `border-radius:4px;font-size:12px;white-space:nowrap;background:${theme.colors.background.secondary};` +
    `color:${theme.colors.text.primary};border:1px solid ${theme.colors.border.weak};` +
    'box-shadow:0 2px 8px rgba(0,0,0,.35)}' +
    '.liq-tip-title{font-weight:600;margin-bottom:2px}' +
    '.liq-tip table{border-collapse:collapse}' +
    '.liq-tip th,.liq-tip td{padding:1px 10px 1px 0;text-align:left;font-weight:normal}' +
    `.liq-tip tr:first-child th{color:${theme.colors.text.secondary ?? theme.colors.text.primary};font-size:11px}` +
    `${TOOLTIP_CARET}{top:0!important;left:0!important;right:0!important;bottom:0!important;` +
    'width:auto!important;height:auto!important;opacity:0!important}' +
    locked.map((table) => `${table} [role="columnheader"] button:not([aria-label])`).join(',') +
    (locked.length ? '{cursor:default}' : '') +
    aligned.join(',') +
    (aligned.length ? '{scrollbar-gutter:stable}' : '') +
    Object.entries(rowTints)
      .map(
        ([name, tint]) =>
          `[role="row"]:has(img[alt^="${name}"]) [role="gridcell"]{background-color:${tint}}`
      )
      .join('') +
    // A fixed slot, so the numbers line up whichever tag follows them.
    `[role="gridcell"][data-liq-unit]::after{content:attr(data-liq-unit);display:inline-block;width:1.6em;` +
    `margin-left:3px;text-align:left;font-size:11px;color:${theme.colors.text.secondary ?? theme.colors.text.primary}}`;
  drawSortArrows(doc, panel);
  tagUnits(doc, panel, unitTags);

  for (const [type, listener, capture] of doc.liqBoardTablesListeners ?? []) {
    doc.removeEventListener(type, listener, capture);
  }
  let tip = doc.querySelector('.liq-tip');
  if (!tip) {
    tip = doc.createElement('div');
    tip.className = 'liq-tip';
    tip.hidden = true;
    doc.body.appendChild(tip);
  }
  const hideTip = () => {
    tip.hidden = true;
  };

  // The tip for a header named in headerTips, under its panel's title.
  const headerTip = (target) => {
    const header = target.closest?.('[role="columnheader"]');
    const section = header?.closest('section[data-testid^="data-testid Panel header "]');
    if (!section) return null;
    const title = section.getAttribute('data-testid').slice(PANEL_TESTID.length);
    return doc.liqHeaderTips[title]?.[header.textContent.trim()] ? header : null;
  };
  const showTip = (anchor, text, html = false) => {
    if (html) tip.innerHTML = text;
    else tip.textContent = text;
    tip.hidden = false;
    const box = anchor.getBoundingClientRect();
    const view = doc.documentElement.clientWidth;
    const left = Math.min(Math.max(4, box.left + box.width / 2 - tip.offsetWidth / 2), view - tip.offsetWidth - 4);
    tip.style.left = `${left}px`;
    tip.style.top = `${Math.max(4, box.top - tip.offsetHeight - 6)}px`;
  };

  const onOver = (event) => {
    const header = headerTip(event.target);
    if (header) {
      const title = header.closest('section').getAttribute('data-testid').slice(PANEL_TESTID.length);
      showTip(header, doc.liqHeaderTips[title][header.textContent.trim()]);
      return;
    }
    const light = event.target.closest?.(TIP_CELL);
    if (!light) return;
    // The browser shows `title` on its own too, so the text moves out of it.
    if (light.hasAttribute('title')) {
      light.dataset.liqTip = light.getAttribute('title');
      light.removeAttribute('title');
    }
    const text = light.dataset.liqTip;
    if (!text) return;
    if (text.startsWith(ROW_TIP)) {
      const section = light.closest('section[data-testid^="data-testid Panel header "]');
      const title = section?.getAttribute('data-testid').slice(PANEL_TESTID.length);
      if (doc.liqRowTips[title]) showTip(light, rowTipHtml(doc, title, text.slice(ROW_TIP.length)), true);
      return;
    }
    showTip(light, text);
  };
  const onOut = (event) => {
    if (event.target.closest?.(TIP_CELL) || headerTip(event.target)) hideTip();
  };
  // Capture on the document runs before Grafana's own handlers, so the
  // click never reaches the table.
  const onClick = (event) => {
    const name = event.target.closest?.('[role="columnheader"] button');
    if (!name || name.hasAttribute('aria-label')) return;
    if (!doc.liqLockedTables.some((table) => name.closest(table))) return;
    event.stopPropagation();
    event.preventDefault();
    const section = name.closest('section[data-testid^="data-testid Panel header "]');
    const title = section.getAttribute('data-testid').slice(PANEL_TESTID.length);
    const header = name.closest('[role="columnheader"]');
    treeSort(doc, doc.liqPanelSelector, title, name.textContent.trim(), header.getAttribute('aria-colindex'));
  };
  doc.liqBoardTablesListeners = [
    ['mouseover', onOver, false],
    ['mouseout', onOut, false],
    ['scroll', hideTip, true],
    ['click', onClick, true],
  ];
  for (const [type, listener, capture] of doc.liqBoardTablesListeners) {
    doc.addEventListener(type, listener, capture);
  }
};


// Lays out the Dashboard tab's two columns to fit the window. The generator
// prepends this file to header.js, which calls it on every render;
// observability/tests/board-layout.test.ts imports it as a module through the
// export line, which the generator drops.
//
// This ends both columns at the window's bottom, again on every resize: on
// the last whole grid unit that fits, and the two bottom panels then
// stretch over the pixels left (a CSS rule on their grid items, since the
// grid only moves in whole units). In the left column each `fit` table
// takes the grid units its rows need and `fill` the rest; the `split`
// panels of the right column share it equally. Without the page's panels
// to measure, both columns end on the lower of the generator's two
// bottoms. The header takes Grafana's autofit off this board: it would
// squeeze every panel into a short window instead of letting it scroll.
//
// It reaches the layout through window.__grafanaSceneContext, the dashboard
// scene Grafana exposes for debugging. Without it, or without the panels,
// the board keeps the generator's heights.

// A grid unit is a 30px cell and an 8px margin. A table panel needs its
// title bar, padding and header row (91px) plus the margin, and a row per
// table row at the "md" cell height.
const GRID_UNIT_PX = 38;
const GRID_MARGIN_PX = 8;
// The page's own margin under the last panels.
const PAGE_BOTTOM_PX = 8;
const TABLE_CHROME_PX = 99;
const TABLE_ROW_PX = 42;
// Below Grafana's md breakpoint the dashboard is one column of full-width
// panels, a phone's. Grafana stacks them in grid order, in the page's flow,
// which puts Trades between the USD tables; this orders the left column's
// tables first and the right column's after them instead (CSS rules on the
// grid and its items, as for the stretch). A USD table takes the height its
// rows need, and the long tables a share of the screen under Grafana's top
// bar, so they scroll inside and the page still shows the next panel's
// title.
const PHONE_LAYOUT_MAX_PX = 768;
const PHONE_TOP_BAR_PX = 48;
const PHONE_SCROLL_SHARE = 0.75;
const MIN_PHONE_TABLE_PX = 300;
// A phone's table is a pixel taller than the desktop's sum, so a USD table
// sized to its rows would scroll by that pixel.
const PHONE_TABLE_SLACK_PX = 2;
// Grafana pins its dashboard controls (time range, variables and links)
// over a phone's board, a quarter of the screen. On a phone the controls
// scroll away with the board instead: the page scrolls, not the board's
// own container. A panel's time range ("Last 5 minutes") hides too: on a
// phone it cuts off the title's total. The controls themselves wrap to
// five rows on a phone; there they are one row that scrolls sideways: the
// environment, the tab links, then the time range and refresh, without the
// buttons a phone does not need (moving and zooming the time range,
// sharing and editing). Only on a page with this board's Equities panel,
// since the style stays in the page when Grafana opens another dashboard.
const PHONE_SPLITTER = '[data-testid="data-testid DashboardEditPaneSplitter primary body"]';
const PHONE_BODY = '[data-testid="data-testid DashboardEditPaneSplitter body container"]';
const PHONE_CONTROLS = '[data-testid="data-testid dashboard controls"]';
const PHONE_HIDDEN_CONTROLS = [
  '[data-testid*="timepicker-move"]',
  '[data-testid*="timepicker-zoom-out"]',
  ':has(> [data-testid="data-testid Edit dashboard button"])',
];

// A window too short to give the fill table this much (three rows) gets it
// anyway, and the page scrolls: a squeezed Equities of one or two rows is
// worse than a page that scrolls by a few.
const MIN_FILL_UNITS = 6;

const unitsFor = (rows) => Math.ceil((TABLE_CHROME_PX + TABLE_ROW_PX * rows) / GRID_UNIT_PX);
const bottomOf = (column) => column[0].state.y + column.reduce((sum, found) => sum + found.state.height, 0);
const panelOf = (found) => `section[data-testid="data-testid Panel header ${found.state.body.state.title}"]`;
const sectionOf = (doc, found) => doc?.querySelector(panelOf(found));

// The page scroll, controls and time range rules, for the board whose panel
// `board` names. They scope to the page through `body:has(...)`: a :has()
// inside another is not valid CSS, and the browser drops the whole rule.
const phoneScroll = (board) => {
  const page = `body:has(${board})`;
  const splitter = `${page} ${PHONE_SPLITTER}`;
  const controls = `${page} ${PHONE_CONTROLS}`;
  const links = `${controls} > [class*="dashboard-links"]`;
  const time = `${controls} > :has([data-testid="data-testid TimePicker Open Button"])`;
  return (
    `@media (max-width:${PHONE_LAYOUT_MAX_PX}px){` +
    `${page} :has(> ${PHONE_SPLITTER}){overflow-y:auto!important}` +
    `${splitter}{overflow:visible!important;flex:none!important;height:auto!important}` +
    `${splitter} ${PHONE_BODY}{overflow:visible!important;flex:none!important;height:auto!important}` +
    `${splitter} [data-testid="title-items-container"] > :has([data-testid="icon-clock-nine"]){display:none!important}` +
    `${controls}{display:flex!important;flex-flow:row nowrap!important;align-items:center!important;gap:8px!important;` +
    `overflow-x:auto!important;scrollbar-width:none!important;padding:8px 16px!important}` +
    `${controls} > *{flex:none!important;margin:0!important;width:auto!important}` +
    `${controls} [data-testid="data-testid template variable"]{order:1}` +
    `${links}{order:2;display:flex!important;flex-wrap:nowrap!important;gap:8px!important}` +
    `${links} > *{flex:none!important;margin:0!important}` +
    `${time}{order:3;display:flex!important;flex-direction:row!important;gap:8px!important}` +
    PHONE_HIDDEN_CONTROLS.map((hidden) => `${controls} ${hidden}`).join(',') +
    `{display:none!important}}`
  );
};

// The phone stack's rules: the header (the grid's first item) first, then
// `column`'s panels in that order, `heights` px each. Any other item is the
// row detail's (detail.js): empty, with its margin a gap under the header.
// Its dialog opens in the page's top layer, so that item takes no room.
const phoneStack = (column, heights) => {
  const grid = `.react-grid-layout:has(> .react-grid-item ${panelOf(column[0])})`;
  const others = column.map((found) => `:not(:has(${panelOf(found)}))`).join('');
  return (
    `${grid}{display:flex!important;flex-direction:column!important;height:auto!important}` +
    `${grid} > .react-grid-item:not(:first-child)${others}{height:0!important;margin:0!important;overflow:hidden!important}` +
    column
      .map((found, index) => {
        const panel = panelOf(found);
        return (
          `.react-grid-item:has(${panel}){order:${index + 1}!important;height:${heights[index]}px!important}` +
          `${panel}{height:${heights[index]}px!important}`
        );
      })
      .join('')
  );
};

// How far the boxes around `element` have scrolled it up.
const scrolledAbove = (element) => {
  let scrolled = 0;
  for (let node = element.parentElement; node; node = node.parentElement) scrolled += node.scrollTop || 0;
  return scrolled;
};

// Where the window ends, in grid units and the pixels past the last whole
// unit, from where `first` sits on the page; null without it. The page
// position, not the scrolled one: a short window scrolls, and a reflow
// after a scroll must not grow the tables by what was scrolled.
const windowBottom = (win, first) => {
  const section = sectionOf(win.document, first);
  if (!section || !(win.innerHeight > 0)) return null;
  const top = section.getBoundingClientRect().top + scrolledAbove(section);
  const origin = top - first.state.y * GRID_UNIT_PX;
  // An item `n` units down ends at origin + n units, less one margin.
  const room = win.innerHeight - PAGE_BOTTOM_PX - origin + GRID_MARGIN_PX;
  const units = Math.floor(room / GRID_UNIT_PX);
  return { units, extraPx: Math.floor(room - units * GRID_UNIT_PX) };
};

const fitColumns = (scene, { fit, fill, split }, win) => {
  const grid = scene?.state?.body?.state?.grid;
  if (!grid?.state?.children || grid.liqFitColumns) return;

  const item = (title) => grid.state.children.find((child) => child.state.body?.state?.title === title);
  const left = [...fit, fill].map(item);
  const right = split.map(item);
  if ([...left, ...right].some((found) => !found)) return;
  grid.liqFitColumns = true;

  // The rows each table draws: its query's frame after the panel's
  // transformations, one row per venue. None until the data arrives.
  const rows = (found) => found.state.body.state.$data?.state?.data?.series?.[0]?.length;

  // The page's style for the board: `css` after the phone's scroll rule and
  // a dark, thin scrollbar (the system's light one is the brightest thing on
  // a dark board).
  const restyle = (css) => {
    const doc = win.document;
    if (!doc?.head) return;
    let style = doc.getElementById('liq-board-stretch');
    if (!style) {
      style = doc.createElement('style');
      style.id = 'liq-board-stretch';
      doc.head.appendChild(style);
    }
    const board = panelOf(left[left.length - 1]);
    style.textContent =
      phoneScroll(board) +
      `html:has(${board}),body:has(${board}) *{scrollbar-color:#3a3d45 transparent;scrollbar-width:thin}` +
      css;
  };

  // The bottom panels `extraPx` taller than their grid units, so the columns
  // end at the window's bottom; `bottoms` are [item, its height in units].
  const stretch = (extraPx, bottoms) =>
    restyle(
      extraPx > 0
        ? bottoms
            .map(([found, units]) => {
              const panel = panelOf(found);
              const px = units * GRID_UNIT_PX - GRID_MARGIN_PX + extraPx;
              return `.react-grid-item:has(${panel}),${panel}{height:${px}px!important}`;
            })
            .join('')
        : '',
    );

  // A phone's table `rows` long in px.
  const tablePx = (rows) => TABLE_CHROME_PX - GRID_MARGIN_PX + TABLE_ROW_PX * rows + PHONE_TABLE_SLACK_PX;

  const phone = () => {
    const scrolling = Math.max(
      MIN_PHONE_TABLE_PX,
      Math.round((win.innerHeight - PHONE_TOP_BAR_PX) * PHONE_SCROLL_SHARE),
    );
    // The long tables scroll inside; a USD table keeps its height until its
    // data arrives.
    const heights = [...left, ...right].map((found, index) => {
      const count = rows(found);
      if (index >= left.length - 1) return count ? Math.min(tablePx(count), scrolling) : scrolling;
      return count ? tablePx(count) : found.state.height * GRID_UNIT_PX - GRID_MARGIN_PX;
    });
    restyle(phoneStack([...left, ...right], heights));
  };

  const reflow = () => {
    if (win.innerWidth > 0 && win.innerWidth <= PHONE_LAYOUT_MAX_PX) {
      phone();
      return;
    }
    const fits = windowBottom(win, left[0]);
    const fitted = left.slice(0, -1).map((found) => {
      const count = rows(found);
      return count ? unitsFor(count) : found.state.height;
    });
    const above = left[0].state.y + fitted.reduce((sum, height) => sum + height, 0);
    const room = (fits ? fits.units : Math.max(bottomOf(left), bottomOf(right))) - above;
    const short = room < MIN_FILL_UNITS;
    const rest = short ? MIN_FILL_UNITS : room;
    const bottom = above + rest;

    const rightTotal = bottom - right[0].state.y;
    const share = Math.floor(rightTotal / right.length);
    const shares = right.map((_, index) => (index === right.length - 1 ? rightTotal - share * index : share));

    let changed = false;
    const place = (column, heights) => {
      let y = column[0].state.y;
      heights.forEach((height, index) => {
        const found = column[index];
        // Only real changes, so a reflow that its own update triggers stops.
        if (found.state.y !== y || found.state.height !== height) {
          found.setState({ y, height });
          changed = true;
        }
        y += height;
      });
    };
    place(left, [...fitted, rest]);
    place(right, shares);
    // A short window's page scrolls, so there is no bottom to stretch to.
    stretch(fits && !short ? fits.extraPx : 0, [
      [left[left.length - 1], rest],
      [right[right.length - 1], shares[shares.length - 1]],
    ]);
    // The grid draws its items' new places only when told to.
    if (changed) grid.forceRender?.();
  };

  reflow();
  left.forEach((found) => found.state.body.state.$data?.subscribeToState?.(reflow));
  // The window's bottom moves when it changes size. One
  // listener per window: a new dashboard scene replaces the last one's,
  // which would keep the old scene alive and reflow it on every resize.
  if (win.liqFitColumnsResize) win.removeEventListener?.('resize', win.liqFitColumnsResize);
  win.liqFitColumnsResize = () => win.setTimeout(reflow, 0);
  win.addEventListener('resize', win.liqFitColumnsResize);
};


// Each inventory table's total in USD, after its title. The generator
// prepends this file to header.js, which calls it on every render;
// observability/tests/board-totals.test.ts imports it as a module through the
// export line, which the generator drops.
//
// A panel title is fixed text in Grafana, so the total is a CSS ::after on
// the title, from the panel's own data in the dashboard scene
// (window.__grafanaSceneContext): the sum of the named columns over every
// row, by their field names (organize only renames for display). It follows
// each panel's data as it refreshes. Without the scene, or before the data
// arrives, a title shows no total. A NaN cell is a value the generator
// could not price (an asset without a live price), so the total then says
// it is partial; an empty cell (null) is only a row without that column.
//
// A table's entry is its columns, or { columns, stamp, staleAfterSeconds }:
// `stamp` names a column of Unix seconds (when each row's price was quoted),
// and the title also says how old the oldest is once it is older than
// `staleAfterSeconds`, since its values then rest on prices that are not
// live. `parts`, [{ label, columns, rows }], adds a total over some rows
// only after the table's own, each "label $N": `rows` is a pattern for the
// row key in the `rowField` column (an Equities chain row is symbol/chain).

const usd = (value) => `$${Math.round(value).toLocaleString('en-US')}`;

// "Oct 16, 23:41 UTC" for Unix seconds.
const utcStamp = (seconds) => {
  const at = new Date(seconds * 1000);
  const month = at.toLocaleString('en-US', { month: 'short', timeZone: 'UTC' });
  const time = at.toISOString().slice(11, 16);
  return `${month} ${at.getUTCDate()}, ${time} UTC`;
};

// The oldest Unix seconds in `column` of a frame, or null.
const oldestStamp = (frame, column) => {
  const values = (frame?.fields ?? []).find((field) => field.name === column)?.values ?? [];
  const stamps = values.map(Number).filter((value) => Number.isFinite(value) && value > 0);
  return stamps.length ? Math.min(...stamps) : null;
};

// The sum of `columns` over every row of a frame (or the rows `keep`
// takes, by index), and whether a cell had no price, or null when none of
// them has a number.
const frameTotal = (frame, columns, keep = () => true) => {
  let sum = 0;
  let found = false;
  let partial = false;
  for (const field of frame?.fields ?? []) {
    if (!columns.includes(field.name)) continue;
    for (const [index, value] of [...field.values].entries()) {
      if (!keep(index)) continue;
      if (typeof value === 'number' && Number.isNaN(value)) partial = true;
      const number = Number(value);
      if (value === null || value === '' || !Number.isFinite(number)) continue;
      sum += number;
      found = true;
    }
  }
  return found ? { sum, partial } : null;
};

const showTotals = (doc, scene, totals, now = () => Date.now()) => {
  const grid = scene?.state?.body?.state?.grid;
  if (!grid?.state?.children) return;
  const panel = (title) => grid.state.children.find((child) => child.state.body?.state?.title === title)?.state.body;

  let style = doc.getElementById('liq-board-totals');
  if (!style) {
    style = doc.createElement('style');
    style.id = 'liq-board-totals';
    doc.head.appendChild(style);
  }
  const draw = () => {
    style.textContent = Object.entries(totals)
      .map(([title, spec]) => {
        const { columns, stamp, staleAfterSeconds = 0, parts = [], rowField } = Array.isArray(spec)
          ? { columns: spec }
          : spec;
        const frame = panel(title)?.state?.$data?.state?.data?.series?.[0];
        const total = frameTotal(frame, columns);
        if (total === null) return '';
        const keys = (frame?.fields ?? []).find((field) => field.name === rowField)?.values ?? [];
        const split = parts
          .map(({ label, columns: partColumns, rows }) => {
            const pattern = new RegExp(rows);
            const part = frameTotal(frame, partColumns, (index) => pattern.test(String(keys[index] ?? '')));
            return part === null ? '' : ` \\00B7  ${label} ${usd(part.sum)}`;
          })
          .join('');
        const oldest = stamp ? oldestStamp(frame, stamp) : null;
        const stale = oldest !== null && now() / 1000 - oldest > staleAfterSeconds;
        const text =
          usd(total.sum) +
          (total.partial ? ' (some unpriced)' : '') +
          split +
          (stale ? ` \\00B7  prices as of ${utcStamp(oldest)}` : '');
        return (
          `section[data-testid="data-testid Panel header ${title}"] h2::after` +
          `{content:" \\00B7  ${text}";font-weight:400}`
        );
      })
      .join('');
  };
  draw();

  if (grid.liqTotals) return;
  grid.liqTotals = true;
  Object.keys(totals).forEach((title) => panel(title)?.state?.$data?.subscribeToState?.(draw));
};


// Scales the inventory tables down on a narrow window. The generator
// prepends this file to header.js, which calls it on every render;
// observability/tests/board-scale.test.ts imports it as a module through the
// export line, which the generator drops.
//
// Each table's columns have fixed widths that add up to `fixedPx`, then the
// ratio bar takes the rest. On a window too narrow for them and `ratioMinPx`
// of bar, the table would scroll sideways and squeeze the bar. Instead every
// fixed width shrinks by the same factor, and the text with it, so the table
// fits its panel and the bar keeps its room. The tables share the factor, so
// their bars still line up. Grafana sizes a table's columns from the panel's
// own measure, so CSS zoom cannot do this: the widths change in each panel's
// field config in the dashboard scene (window.__grafanaSceneContext), and the
// font size in a CSS rule. Without the scene the tables keep their widths.
//
// A table's width changes without a window resize too: Grafana often draws
// the tables after the header first runs this, the layout moves the panels,
// and the sidebar opens and closes. So each table's panel is
// watched for its own size (ResizeObserver), and for a new table element
// inside it (MutationObserver), which is when Grafana first draws the
// table or draws it again; a scroll only changes cells, so it runs
// nothing.
//
// Each group of tables (`id`) has its own factor, rule, observer and
// listener: the left column's tables share one so their bars line up, and
// the trade and transfer tables each have their own.
//
// Grafana stretches a table's last column with no width over the panel's
// whole width, the scrollbar's place included, so that table scrolls
// sideways by the scrollbar's width at any size. A group that names its
// `stretch` column gets it pinned to what the other columns leave of the
// table's visible width, at least `stretchMinPx`.

// Grafana draws no column narrower than this, whatever its width says.
const MIN_COLUMN_PX = 50;

// A table that would need its text under COMPACT_BELOW to fit every column
// (about 10px), and every table on a phone (below Grafana's md breakpoint,
// one column of full-width panels), is compact: its group hides
// the columns `compactHide` names ({panel title: [column]}), changes the
// properties `compactColumns` names ({column: {property id: value}}, a
// shorter time format and its narrower width, say) and fits the rest,
// `compactFixedPx` wide, with `compactRatioMinPx` of stretching column.
// A 16-inch MacBook with Grafana's menu docked (about 0.74) keeps every
// column, smaller; a 1440px laptop (about 0.6) goes compact at full size.
const PHONE_MAX_PX = 768;
const COMPACT_BELOW = 0.72;

// `fieldConfig` with each column's properties changed to `changes`
// ({column: {property id: value}}) where its overrides set them.
const changedFieldConfig = (fieldConfig, changes) => ({
  ...fieldConfig,
  overrides: fieldConfig.overrides.map((override) => {
    const values = changes[override.matcher.options];
    if (!values) return override;
    return {
      ...override,
      properties: override.properties.map((property) =>
        property.id in values ? { ...property, value: values[property.id] } : property
      ),
    };
  }),
});

// `fieldConfig` with the columns `names` hidden.
const hiddenFieldConfig = (fieldConfig, names) => {
  const hide = { id: 'custom.hideFrom.viz', value: true };
  const listed = new Set(fieldConfig.overrides.map((override) => override.matcher.options));
  return {
    ...fieldConfig,
    overrides: [
      ...fieldConfig.overrides.map((override) =>
        names.includes(override.matcher.options) ? { ...override, properties: [...override.properties, hide] } : override
      ),
      ...names.filter((name) => !listed.has(name)).map((name) => ({ matcher: { id: 'byName', options: name }, properties: [hide] })),
    ],
  };
};
const hidden = (override) =>
  override.properties.some((property) => property.id === 'custom.hideFrom.viz' && property.value === true);

// Below this the text gets too small to read; the table scrolls instead.
const MIN_TABLE_SCALE = 0.6;
// The cells' font size at full scale (Grafana's table body).
const TABLE_FONT_PX = 14;

// The factor for a table `width` px wide: 1 when the columns and the bar
// fit, else smaller, in steps of 0.02 so a resize does not redraw for every
// pixel.
const tableScale = (width, fixedPx, ratioMinPx) => {
  if (!(width > 0)) return 1;
  const fit = width / (fixedPx + ratioMinPx);
  if (fit >= 1) return 1;
  return Math.max(MIN_TABLE_SCALE, Math.floor(fit * 50) / 50);
};

// `fieldConfig` with every fixed width times `scale`, each also its column's
// minimum (Grafana's default minimum, 50px, would stop it shrinking).
const scaledFieldConfig = (fieldConfig, scale) => ({
  ...fieldConfig,
  overrides: fieldConfig.overrides.map((override) => {
    const width = override.properties.find((property) => property.id === 'custom.width');
    if (!width) return override;
    const px = Math.round(width.value * scale);
    return {
      ...override,
      properties: [
        ...override.properties.filter((property) => property.id !== 'custom.width' && property.id !== 'custom.minWidth'),
        { id: 'custom.width', value: px },
        { id: 'custom.minWidth', value: px },
      ],
    };
  }),
});

// `fieldConfig` with the column `name` exactly `px` wide.
const pinnedFieldConfig = (fieldConfig, name, px) => {
  const pin = { id: 'custom.width', value: px };
  const pinned = fieldConfig.overrides.some((override) => override.matcher.options === name);
  return {
    ...fieldConfig,
    overrides: pinned
      ? fieldConfig.overrides.map((override) =>
          override.matcher.options === name
            ? { ...override, properties: [...override.properties.filter((property) => property.id !== 'custom.width'), pin] }
            : override
        )
      : [...fieldConfig.overrides, { matcher: { id: 'byName', options: name }, properties: [pin] }],
  };
};

// What the columns of `fieldConfig` other than `stretch` leave of a table
// `width` px wide, each counted at Grafana's minimum at least, and never
// under `minPx`.
const stretchLeft = (fieldConfig, width, stretch, minPx) => {
  const others = fieldConfig.overrides
    .filter((override) => override.matcher.options !== stretch && !hidden(override))
    .flatMap((override) => override.properties.filter((property) => property.id === 'custom.width'))
    .reduce((sum, property) => sum + Math.max(MIN_COLUMN_PX, property.value), 0);
  return Math.max(minPx, Math.floor(width - others));
};

const scaleTables = (
  doc,
  scene,
  {
    id = '',
    panels,
    fixedPx,
    ratioMinPx,
    stretch,
    stretchMinPx = 0,
    cellFontPx,
    compactHide = {},
    compactColumns = {},
    compactFixedPx = fixedPx,
    compactRatioMinPx = ratioMinPx,
  },
  win
) => {
  const grid = scene?.state?.body?.state?.grid;
  if (!grid?.state?.children || panels.length === 0) return;
  const vizPanel = (title) => grid.state.children.find((child) => child.state.body?.state?.title === title)?.state.body;
  const section = (title) => `section[data-testid="data-testid Panel header ${title}"]`;

  const styleId = id ? `liq-board-scale-${id}` : 'liq-board-scale';
  let style = doc.getElementById(styleId);
  if (!style) {
    style = doc.createElement('style');
    style.id = styleId;
    doc.head.appendChild(style);
  }

  const apply = () => {
    // The tables share one width (one column), so the first one present
    // sets the factor for all.
    const table = panels.map((title) => doc.querySelector(`${section(title)} [role="grid"]`)).find(Boolean);
    const width = table?.clientWidth;
    const compact =
      (win.innerWidth > 0 && win.innerWidth <= PHONE_MAX_PX) ||
      (width > 0 && width / (fixedPx + ratioMinPx) < COMPACT_BELOW);
    const scale = compact
      ? tableScale(width, compactFixedPx, compactRatioMinPx)
      : tableScale(width, fixedPx, ratioMinPx);
    // The headers at Grafana's size, scaled; the cells at the group's own
    // size when it sets one.
    style.textContent =
      (scale < 1
        ? panels.map((title) => `${section(title)} [role="grid"]`).join(',') +
          `{font-size:${(TABLE_FONT_PX * scale).toFixed(1)}px}`
        : '') +
      (cellFontPx
        ? panels.map((title) => `${section(title)} [role="gridcell"]`).join(',') +
          `{font-size:${(cellFontPx * scale).toFixed(1)}px}`
        : '');
    for (const title of panels) {
      const panel = vizPanel(title);
      if (!panel?.onFieldConfigChange) continue;
      panel.liqFieldConfig = panel.liqFieldConfig || panel.state.fieldConfig;
      const base = compact
        ? changedFieldConfig(hiddenFieldConfig(panel.liqFieldConfig, compactHide[title] ?? []), compactColumns)
        : panel.liqFieldConfig;
      let next = scale < 1 ? scaledFieldConfig(base, scale) : base;
      let applied = `${compact ? 'compact' : 'wide'}|${scale}`;
      const own = doc.querySelector(`${section(title)} [role="grid"]`);
      if (stretch && own?.clientWidth > 0) {
        // Its text shrinks with the others, so its minimum does too.
        const px = stretchLeft(next, own.clientWidth, stretch, Math.round(stretchMinPx * scale));
        next = pinnedFieldConfig(next, stretch, px);
        applied += `|${px}`;
      }
      if (panel.liqScale === applied) continue;
      panel.liqScale = applied;
      panel.onFieldConfigChange(next);
    }
  };
  // Each render watches the panels present now; Grafana can replace a
  // panel's element, so the last render's observer goes.
  const watch = () => {
    doc.liqScaleObservers = doc.liqScaleObservers || {};
    for (const observer of doc.liqScaleObservers[id] ?? []) observer.disconnect();
    const observers = [];
    const sections = panels.map((title) => doc.querySelector(section(title))).filter(Boolean);
    if (win.ResizeObserver) {
      const observer = new win.ResizeObserver(() => win.setTimeout(apply, 0));
      for (const found of sections) observer.observe(found);
      observers.push(observer);
    }
    if (win.MutationObserver) {
      for (const found of sections) {
        let drawn = found.querySelector('[role="grid"]');
        const observer = new win.MutationObserver(() => {
          const table = found.querySelector('[role="grid"]');
          if (table === drawn) return;
          drawn = table;
          win.setTimeout(apply, 0);
        });
        observer.observe(found, { childList: true, subtree: true });
        observers.push(observer);
      }
    }
    doc.liqScaleObservers[id] = observers;
    apply();
  };
  watch();

  grid.liqScaleTables = grid.liqScaleTables || {};
  if (grid.liqScaleTables[id]) return;
  grid.liqScaleTables[id] = true;
  for (const title of panels) vizPanel(title)?.state?.$data?.subscribeToState?.(() => win.setTimeout(watch, 0));
  // One listener per window and group, as in board-layout.js: a new scene
  // replaces the last one's.
  win.liqScaleTablesResize = win.liqScaleTablesResize || {};
  if (win.liqScaleTablesResize[id]) win.removeEventListener?.('resize', win.liqScaleTablesResize[id]);
  win.liqScaleTablesResize[id] = () => win.setTimeout(apply, 0);
  win.addEventListener('resize', win.liqScaleTablesResize[id]);
};


// Loads the Trades and Rebalances tables in two steps. The generator
// prepends this file to header.js, which calls it on every render;
// observability/tests/board-progressive.test.ts imports it as a module
// through the export line, which the generator drops.
//
// A log table's panel asks for only the newest entries that fill a screen
// (its maxDataPoints, the row limit of the Cloud Logging plugin), so the
// board shows its first rows as soon as the other panels. Once that first
// answer is in, the table asks again for its whole history, `full` entries,
// and Grafana keeps the first rows on screen while the rest loads. A
// refresh then reads the whole history, as the table already shows it.
//
// It reaches the panels through window.__grafanaSceneContext, the dashboard
// scene Grafana exposes for debugging. Without it the tables keep their
// first rows only.

// The query runner under a panel: its data, under any transformations.
const queryRunner = (panel) => {
  let data = panel?.state?.$data;
  while (data && !data.state?.queries && data.state?.$data) data = data.state.$data;
  return data?.runQueries ? data : null;
};

// `panels`: {panel title: entries in its whole history}.
const loadInFull = (scene, panels) => {
  const grid = scene?.state?.body?.state?.grid;
  if (!grid?.state?.children) return;
  for (const [title, full] of Object.entries(panels)) {
    const panel = grid.state.children.find((child) => child.state.body?.state?.title === title)?.state.body;
    const runner = queryRunner(panel);
    // Once per runner: a new dashboard scene brings new runners.
    if (!runner || runner.liqFullLoad) continue;
    runner.liqFullLoad = true;
    const widen = () => {
      if (runner.state.data?.state !== 'Done' || !(runner.state.maxDataPoints < full)) return false;
      runner.setState({ maxDataPoints: full });
      runner.runQueries();
      return true;
    };
    if (widen()) continue;
    const subscription = runner.subscribeToState(() => {
      if (widen() || runner.state.maxDataPoints >= full) subscription?.unsubscribe?.();
    });
  }
};


// Business Text "afterRender" code for the Liquidity bot header: the bot's
// status and settings in one row, with the Config and CLI recovery guide
// dialogs.
//
// Input: context.data, rows with a `k` column naming the value (up, uptime,
// commit, info, equity_target, ...) plus the string labels some of them
// carry (git_commit on commit; broker, wallet_kind, ... on info).
//
// RECOVERY_GUIDE, readHeaderRows, readWrapperRatios, commandLine, wireCopyButtons,
// installBoardTables, fitColumns, showTotals, scaleTables and loadInFull are
// not defined here: the generator prepends them from recovery-guide.json,
// header-rows.js, copy-command.js, board-tables.js, board-layout.js,
// board-totals.js, board-scale.js and board-progressive.js (see pills() in
// the generator), because
// the template output is sanitized and cannot carry data into this code.

const rows = Array.isArray(context.data) ? context.data : [];
// header-rows.js, prepended.
const { value, commit, info } = readHeaderRows(rows);

// The Dashboard tab fits the window itself (FIT_WINDOW, prepended;
// board-layout.js): it fills a tall window to the bottom and lets a short
// one, or a phone, scroll. Grafana's autofit would squeeze every panel into
// one screen however short it is, so it comes off a link that has it. It
// changes the URL in place.
const autofit = new URLSearchParams(window.location.search).has('autofitpanels');
if (FIT_WINDOW && autofit) {
  context.grafana.locationService.partial({ autofitpanels: null }, true);
}
// Then the left column's USD tables take only the rows they draw, Equities
// the rest, Trades and Rebalances half of the right column each, and both
// columns end level (FIT_COLUMNS, prepended; board-layout.js). Once per
// dashboard.
if (FIT_COLUMNS) fitColumns(window.__grafanaSceneContext, FIT_COLUMNS, window);
// Each inventory table's total in USD after its title (TABLE_TOTALS,
// prepended; board-totals.js).
showTotals(document, window.__grafanaSceneContext, TABLE_TOTALS);
// The tables shrink on a narrow window, each group by its own factor, so
// they fit without scrolling sideways (SCALE_TABLES, prepended;
// board-scale.js).
for (const group of SCALE_TABLES) scaleTables(document, window.__grafanaSceneContext, group, window);
// The log tables show a screen's entries first, then load their whole
// history (FULL_ENTRIES, prepended; board-progressive.js).
loadInFull(window.__grafanaSceneContext, FULL_ENTRIES);

const theme = context.grafana.theme;
// Hover text for table cells, the locked sort of tree tables, the fitted
// column's aligned edges, each venue row's tint, the headers' hover text,
// the tree tables' own sort, and each symbol's flags on hover
// (board-tables.js, LOCKED_SORT_PANELS,
// FIT_COLUMNS, ROW_TINTS, HEADER_TIPS, TREE_SORTS and ROW_TIPS, prepended).
installBoardTables(document, {
  lockedSortPanels: LOCKED_SORT_PANELS,
  // Every table keeps room for its scrollbar: Grafana stretches the last
  // column over the scrollbar's place too, which scrolls a fitted table
  // sideways by the scrollbar's width.
  alignedPanels: FIT_COLUMNS ? [...FIT_COLUMNS.fit, FIT_COLUMNS.fill, ...FIT_COLUMNS.split] : [],
  rowTints: ROW_TINTS,
  headerTips: HEADER_TIPS,
  treeSorts: TREE_SORTS,
  rowTips: ROW_TIPS,
  unitTags: UNIT_TAGS,
  wrapperRatios: readWrapperRatios(rows),
  theme
});
const root = context.element;
// The guide's commands target the environment the board shows
// (client-env.js, prepended).
const ENV = boardEnv(context.grafana.replaceVariables('${env:text}'));
// The plugin pads each rendered row by 8px, which makes this one-row panel
// scroll; the row has no room for it.
root.style.padding = '0';
root.style.height = '100%';
root.style.overflow = 'hidden';
root.style.setProperty('--hdr-muted', theme.colors.text.secondary);
// Light theme swaps the mode colours for darker shades (header.css).
root.classList.toggle('hdr-light', !theme.isDark);
root.style.setProperty('--hdr-border', theme.colors.border.weak);
root.style.setProperty('--hdr-pill', theme.colors.background.secondary);
root.style.setProperty('--hdr-card', theme.colors.background.primary);
root.style.setProperty('--hdr-text', theme.colors.text.primary);

const escapeHtml = (text) =>
  String(text ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);

// A percent and a band: "50%" and "45%–55%".
const pct = (fraction) => `${(fraction * 100).toFixed(0)}%`;
const band = (target, deviation) =>
  target === null || target === undefined
    ? ''
    : deviation === null || deviation === undefined
      ? ''
      : ` <span class="hdr-muted">(${pct(target - deviation)}–${pct(target + deviation)})</span>`;

// The bot's uptime: "up 3d 4h", "up 4h 12m" or "up 12m".
const uptime = (seconds) => {
  if (seconds === null || seconds === undefined) return '';
  const days = Math.floor(seconds / 86400);
  const hours = Math.floor((seconds % 86400) / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  if (days > 0) return `up ${days}d ${hours}h`;
  if (hours > 0) return `up ${hours}h ${minutes}m`;
  return `up ${minutes}m`;
};

const clock = () => new Date().toISOString().replace('T', ' ').slice(0, 19) + ' UTC';

const pill = (inner) => `<span class="hdr-pill">${inner}</span>`;
// 1 up, 0 down; no value means the source is not reporting, which says
// nothing about the bot.
const connection =
  value.up === 1 ? ['hdr-ok', 'Connected'] : value.up === 0 ? ['hdr-bad', 'Disconnected'] : ['hdr-unknown', 'No data'];

const pills = [
  info.broker ? pill(`<span class="hdr-mono">${escapeHtml(info.broker)}</span>`) : '',
  value.equity_target !== null && value.equity_target !== undefined
    ? pill(`Equity <b class="hdr-mono">${pct(value.equity_target)}</b>${band(value.equity_target, value.equity_deviation)}`)
    : '',
  value.usdc_target !== null && value.usdc_target !== undefined
    ? pill(`USDC <b class="hdr-mono">${pct(value.usdc_target)}</b>${band(value.usdc_target, value.usdc_deviation)}`)
    : '',
  value.trigger !== null && value.trigger !== undefined ? pill(`Trigger <b class="hdr-mono">$${value.trigger}</b>`) : '',
  value.cash_reserved !== null && value.cash_reserved !== undefined
    ? pill(`Reserve <b class="hdr-mono">$${value.cash_reserved}</b>`)
    : '',
].join('');

const configRow = (name, text) =>
  `<div class="hdr-row"><span class="hdr-muted">${name}</span><span class="hdr-mono hdr-trunc" title="${escapeHtml(text)}">${escapeHtml(text)}</span></div>`;
const seconds = (number) => (number === null || number === undefined ? '' : `${number}s`);

const configDialog = `
<dialog class="hdr-dialog hdr-narrow" data-dialog="config">
  <div class="hdr-dialog-head"><span>Configuration</span><button class="hdr-close" data-close aria-label="Close">&times;</button></div>
  <div class="hdr-dialog-body hdr-mono">
    ${
      info.wallet_kind
        ? configRow('Wallet', info.wallet_kind) +
          configRow('Address', info.wallet_address) +
          (info.wallet_kind === 'turnkey' && info.turnkey_organization ? configRow('Turnkey org', info.turnkey_organization) : '') +
          '<div class="hdr-rule"></div>'
        : ''
    }
    ${configRow('Exported log level', info.log_level)}
    ${configRow('Server port', info.server_port)}
    ${configRow('Deployment block', value.deployment_block ?? '')}
    ${configRow('Order polling', seconds(value.order_polling))}
    ${configRow('Inventory polling', seconds(value.inventory_polling))}
    ${configRow('Cash reserve', value.cash_reserved !== null && value.cash_reserved !== undefined ? `$${value.cash_reserved}` : 'none')}
    ${configRow('Orderbook', info.orderbook)}
  </div>
</dialog>`;

const guide = RECOVERY_GUIDE;
const modeClass = (mode) =>
  mode === 'requires-bot' ? 'hdr-amber' : 'hdr-red';
const guideDialog = `
<dialog class="hdr-dialog hdr-wide" data-dialog="guide">
  <div class="hdr-dialog-head"><span>CLI recovery guide</span><button class="hdr-close" data-close aria-label="Close">&times;</button></div>
  <div class="hdr-dialog-body">
    <p class="hdr-muted hdr-intro">Every recovery command, grouped by object. They use <span class="hdr-mono">st0x-liquidity-client</span>, which signs in with your Google account and calls the running bot's API, so no SSH is needed and the bot must be running. Some steps need the offline <span class="hdr-mono">stox</span> with the bot stopped instead, for example failing a USDC bridge after its nonce close (<span class="hdr-mono">stox fail-usdc-transfer</span>), and settling a Base to Alpaca bridge by hand after its burn (<span class="hdr-mono">stox transfer reconcile</span>). Each command's description says when.</p>
    ${guide.groups
      .map(
        (group) => `
      <section class="hdr-group">
        <h3 class="hdr-mono">${escapeHtml(group.object)}</h3>
        ${group.commands
          .map(
            (entry) => `
          <div class="hdr-command">
            ${commandLine(escapeHtml(forClientEnv(entry.command, ENV)), 'hdr-mono')}
            <div class="hdr-grid">
              <span class="hdr-muted">What</span><span>${escapeHtml(entry.description)}</span>
              <span class="hdr-muted">When</span><span>${escapeHtml(entry.whenToUse)}</span>
              <span class="hdr-muted">Applies to</span><span>${escapeHtml(entry.appliesTo)}</span>
              <span class="hdr-muted">Mode</span><span class="${modeClass(entry.mode)}">${escapeHtml(guide.modeLabels[entry.mode] || entry.mode)}</span>
            </div>
          </div>`
          )
          .join('')}
      </section>`
      )
      .join('')}
  </div>
</dialog>`;

// The board refreshes every minute and each render replaces the markup, which
// would close a dialog the operator is reading. Remember it to reopen it at
// the same scroll position. A dialog still open in this panel reopens with
// no time limit, however long the operator has been reading it. The memory
// lives on the window, not the element: a refresh with no data shows the
// panel's "No bot data." in place of this markup, the dialog with it, and the
// next render with data reopens it. It is per board page, so another tab's
// header does not open it. The page is read now, not when a handler runs: a
// handler can run after the operator went to another board. Only when the
// dialog is gone does the memory age out, after two of the board's
// one-minute refreshes, with slack for a slow query, so a guide closed by a
// long stretch without data, or left open on a board the operator left, does
// not open by itself much later. Each reopen renews it.
const REOPEN_WITHIN_MS = 150000;
const page = window.location.pathname;
const dialogMemory = window.__liqHeaderDialog || (window.__liqHeaderDialog = { page: null, open: null });
const remembered = dialogMemory.page === page ? dialogMemory.open : null;
// A dismissal clears the memory before the dialog closes (Escape's cancel),
// so a dialog open here that the memory does not name is closing.
const stillOpen = root.querySelector('dialog[open]');
const reopen =
  remembered && stillOpen && stillOpen.dataset.dialog === remembered.name
    ? { name: remembered.name, scroll: stillOpen.querySelector('.hdr-dialog-body').scrollTop }
    : remembered && !stillOpen && Date.now() - remembered.at <= REOPEN_WITHIN_MS
      ? remembered
      : null;

root.innerHTML = `
<div class="hdr">
  <div class="hdr-pills">${pills}</div>
  <button class="hdr-pill hdr-button" data-open="config">Config</button>
  <button class="hdr-guide" data-open="guide">CLI recovery guide</button>
  <span class="hdr-info hdr-muted">${[
    `<span class="hdr-mono" data-clock>${clock()}</span>`,
    commit && commit.sha ? `<span class="hdr-mono" title="Deployed commit">${escapeHtml(commit.sha.slice(0, 7))}</span>` : '',
    value.up === 1 ? `<span title="Bot uptime">${uptime(value.uptime)}</span>` : '',
  ].join('')}</span>
  <span class="hdr-badge ${connection[0]}">${connection[1]}</span>
</div>
${configDialog}
${guideDialog}`;

const remember = (open) => {
  dialogMemory.page = page;
  dialogMemory.open = open && { ...open, at: Date.now() };
};
root.querySelectorAll('[data-open]').forEach((button) => {
  button.addEventListener('click', () => {
    const dialog = root.querySelector(`[data-dialog="${button.dataset.open}"]`);
    dialog.showModal();
    // The body keeps the scroll of an earlier open since the last render.
    remember({ name: button.dataset.open, scroll: dialog.querySelector('.hdr-dialog-body').scrollTop });
  });
});
// The operator's dismissal is recorded when it is asked for: the close
// button, a backdrop click, or Escape (cancel). The close event comes later,
// queued, and a refresh can replace the markup before it runs, which would
// lose the dismissal and reopen the dialog. A callback of a dialog that a
// render or another board already removed is ignored.
root.querySelectorAll('dialog').forEach((dialog) => {
  const dismiss = () => {
    if (dialog.isConnected) remember(null);
    dialog.close();
  };
  dialog.querySelector('[data-close]').addEventListener('click', dismiss);
  // A click on the backdrop closes it.
  dialog.addEventListener('click', (event) => {
    if (event.target === dialog) dismiss();
  });
  dialog.addEventListener('cancel', () => {
    if (dialog.isConnected) remember(null);
  });
  const body = dialog.querySelector('.hdr-dialog-body');
  body.onscroll = () => {
    if (body.isConnected && dialog.open) remember({ name: dialog.dataset.dialog, scroll: body.scrollTop });
  };
});
wireCopyButtons(root);
// The render replaced this panel's dialogs, so a dialog open now is another
// panel's, the row dialog say, and the remembered one must not open over it
// and take its focus.
const reopenDialog = reopen && root.querySelector(`[data-dialog="${reopen.name}"]`);
if (reopenDialog && !document.querySelector('dialog[open]')) {
  reopenDialog.showModal();
  reopenDialog.querySelector('.hdr-dialog-body').scrollTop = reopen.scroll;
  remember({ name: reopen.name, scroll: reopen.scroll });
} else if (dialogMemory.page === page) {
  dialogMemory.open = null;
}

// A ticking UTC clock. One interval per element, replaced on every
// render so a refresh never stacks them. Grafana can also mount a new
// element (tab switch, view mode), so an interval whose element left the
// page stops itself.
clearInterval(root.__hdrClock);
root.__hdrClock = setInterval(() => {
  if (!root.isConnected) {
    clearInterval(root.__hdrClock);
    return;
  }
  const node = root.querySelector('[data-clock]');
  if (node) node.textContent = clock();
}, 1000);

options.styles:
/* Business Text "styles" for the Liquidity bot header row and its two
   dialogs. Theme colours come in as --hdr-* variables set by header.js. */

.hdr {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 100%;
  font-size: 13px;
  white-space: nowrap;
}

/* On a narrow panel only the metric pills and the clock, commit and uptime
   give way, so the Config button, the guide button and the connection badge
   stay in view down to about 330px. They are all direct items of .hdr, so
   no group can shrink below its own controls and push them under the next
   group. The pills clip; the clock, commit and uptime end in an ellipsis. */
.hdr-pills {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
}

/* The clock, commit and uptime give way long before the pills do: a band
   cut to "(551" reads as a wrong number, a clipped commit does not. */
.hdr-info {
  flex: 0 100 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.hdr-info > * + * { margin-left: 8px; }

.hdr-button,
.hdr-guide,
.hdr-badge { flex: 0 0 auto; }

/* Takes the free space, so the guide and what follows sit at the right. */
.hdr-guide { margin-left: auto; }

.hdr-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 10px;
  border-radius: 9999px;
  background: var(--hdr-pill);
  color: var(--hdr-text);
  font-size: 13px;
  line-height: 18px;
  border: 0;
}

.hdr-button {
  color: var(--hdr-muted);
  cursor: pointer;
}

.hdr-button:hover,
.hdr-guide:hover,
.hdr-close:hover {
  color: var(--hdr-text);
}

.hdr-guide {
  padding: 2px 8px;
  border: 1px solid var(--hdr-border);
  border-radius: 4px;
  background: transparent;
  color: var(--hdr-text);
  font-size: 13px;
  line-height: 18px;
  cursor: pointer;
}

.hdr-badge {
  padding: 2px 8px;
  border-radius: 9999px;
  font-size: 13px;
  line-height: 18px;
  font-weight: 600;
}

.hdr-ok { background: #f5f5f5; color: #171717; }
.hdr-bad { background: #ef4444; color: #fff; }
.hdr-unknown { border: 1px solid var(--hdr-border); color: var(--hdr-muted); }

.hdr-mono { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; }
.hdr-muted { color: var(--hdr-muted); }

.hdr-dialog {
  padding: 0;
  border: 1px solid var(--hdr-border);
  border-radius: 8px;
  background: var(--hdr-card);
  color: var(--hdr-text);
  white-space: normal;
}

.hdr-dialog::backdrop { background: rgba(0, 0, 0, 0.5); }
.hdr-narrow { width: min(28rem, 92vw); }
.hdr-wide { width: min(42rem, 92vw); }

.hdr-dialog-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
  border-bottom: 1px solid var(--hdr-border);
  font-size: 14px;
  font-weight: 600;
}

.hdr-close {
  border: 0;
  background: transparent;
  color: var(--hdr-muted);
  font-size: 18px;
  line-height: 1;
  cursor: pointer;
}

.hdr-dialog-body {
  max-height: 70vh;
  overflow-y: auto;
  padding: 16px 20px;
  font-size: 13px;
}

.hdr-row {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 4px 0;
}

.hdr-trunc {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.hdr-rule { border-top: 1px solid var(--hdr-border); margin: 8px 0; }
.hdr-intro { margin: 0 0 16px; }
.hdr-group { margin-bottom: 20px; }
.hdr-group h3 { margin: 0 0 8px; font-size: 13px; text-transform: capitalize; }

.hdr-command {
  margin-bottom: 12px;
  padding: 8px 12px;
  border: 1px solid var(--hdr-border);
  border-radius: 6px;
  background: var(--hdr-pill);
}

.hdr-command pre {
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
  padding: 8px;
  border-radius: 4px;
  background: var(--hdr-card);
  font-size: 12px;
  white-space: pre-wrap;
  word-break: break-all;
}

.hdr-command .liq-command-line {
  display: flex;
  align-items: flex-start;
  gap: 6px;
}

.hdr-command .liq-copy {
  flex: 0 0 auto;
  padding: 4px 8px;
  border: 1px solid var(--hdr-border);
  border-radius: 4px;
  background: var(--hdr-card);
  color: var(--hdr-muted);
  font-size: 12px;
  cursor: pointer;
}

.hdr-command .liq-copy:hover { color: var(--hdr-text); }

.hdr-grid {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 12px;
  margin-top: 6px;
  font-size: 12px;
}

.hdr-amber { color: #f59e0b; }
.hdr-red { color: #ef4444; }

/* Tailwind 700 on the light theme, like detail.css, for a 4.5:1 contrast
   against the white dialog. */
.hdr-light .hdr-amber { color: #b45309; }
.hdr-light .hdr-red { color: #b91c1c; }

/* A phone: the metric pills scroll sideways instead of clipping, so every
   setting stays reachable, and the clock, commit and uptime give their room
   to them. */
/* A phone: the whole header is one row that scrolls sideways, every item
   at its own width, so the band pills are not squeezed out of view. */
@media (max-width: 768px) {
  .hdr {
    overflow-x: auto;
    scrollbar-width: none;
  }
  .hdr::-webkit-scrollbar { display: none; }
  .hdr > * { flex: none; }
  .hdr-pills { overflow: visible; }
  .hdr-info { display: none; }
}

options.afterRender:
const MODE_LABELS = {"requires-bot": "REST \u2014 requires the running bot", "direct-db": "direct DB \u2014 stop the bot / ensure it is not driving this id"};
const ROW_EVENTS = {"datasource": {"type": "googlecloud-logging-datasource", "uid": "cloudlog"}, "filter": "logName=\"projects/$env/logs/liquidity-bot\" jsonPayload.target=\"liq_event\""};

// The operations client a board command runs with. The generator prepends
// this file to header.js and detail.js; observability/tests/recovery.test.ts
// imports it as a module through the export line, which the generator drops.

const LIQUIDITY_CLIENT = 'st0x-liquidity-client --env production';

// The board always knows its environment: the selector's text is production
// or staging.
const boardEnv = (envText) => (envText === 'staging' ? 'staging' : 'production');

const forClientEnv = (command, env) => command.replace('--env production', `--env ${env}`);

const clientFor = (envText) => forClientEnv(LIQUIDITY_CLIENT, boardEnv(envText));


// The board's per-row recovery commands, the source of truth for what the
// row dialog offers. The generator prepends this file to detail.js;
// observability/tests/recovery.test.ts imports it as a module through the
// export line, which the generator drops, and writes every command it shows
// to the files the Rust parser tests read. `client` is the client
// invocation with its --env.

const tradeCommands = (client, symbol) => [
  {
    command: `${client} debug position release-hedge ${symbol} --order-id <order-id> --reason "<reason>"`,
    description: "Clear a position's stuck pending offchain order so normal hedging can retry. Needs the order id.",
    mode: 'requires-bot',
  },
  {
    command: `${client} debug position set ${symbol} --target-net <N> [--price-usdc <USDC_PER_SHARE>] --reason "<reason>"`,
    description:
      'Override the net exposure after a manual correction. The target is signed: negative is short, 0 is flat. The price is required for a nonzero target unless the position already has a last price.',
    mode: 'requires-bot',
  },
  {
    command: `${client} debug view rebuild position --id ${symbol}`,
    description: 'Replay all events to reconstruct a corrupted position view.',
    mode: 'requires-bot',
  },
];

// The stop-first rule for a failed Base to Alpaca bridge. The board offers no
// USDC reconcile row (the status lines do not carry postBurn), so the dialog
// shows it in usdcFailedNote.
const USDC_RECONCILE_BASE_TO_ALPACA =
  ' Base to Alpaca after its burn (not a deposit or conversion failure): unless the mint ' +
  'was reported unresolvable or funds were already moved by hand, keep the bot running ' +
  'and run resume-usdc base-to-alpaca, which re-polls Circle, then mints and sends. ' +
  'Otherwise do not mint, send or reconcile it with the bot running: the bot re-runs its ' +
  'recovery at every start and can send the USDC to Alpaca itself, with no check for an ' +
  'earlier send. Follow docs/cli-ops.md, "Settling a post-burn Base to Alpaca failure by hand".';

// The detail dialog's note for a failed USDC bridge. The Base to Alpaca
// stop-first rule is left out of an Alpaca to Base bridge; a bridge with no
// direction gets it.
const usdcFailedNote = (direction) =>
  'Reconcile applies only when the funds left their source venue, which the logs do not ' +
  'show. Check its events with the client\'s read transfer-events before you reconcile it.' +
  (direction === 'alpaca_to_base' ? '' : USDC_RECONCILE_BASE_TO_ALPACA);

const EQUITY_RECONCILE_INFLIGHT =
  ' If the bot started after this redemption failed at detection or was rejected, its ' +
  'amount stays in flight until the next restart.';

const USDC_FAIL_ALPACA_TO_BASE =
  'Alpaca to Base: the bot accepts this only before the burn, from a completed ' +
  'withdrawal or a burn submission with no recorded burn, and it does not check the ' +
  'chain. A burn the bot sent but did not record can still land, so do not fail the ' +
  'transfer until you have done every check and the nonce close on Ethereum in ' +
  'docs/cli-ops.md, "Clearing a pre-burn guard latch", with the bot stopped. Then fail ' +
  'it with the offline stox fail-usdc-transfer before you start the bot again: a restart ' +
  'sends the burn of a completed withdrawal (at a burn submission, this command after a ' +
  'restart works too). If a burn landed or you are not certain, run resume-usdc instead. ' +
  'The funds left Alpaca, so the guard stays held until you settle them with ' +
  'reconcile-usdc.';

const USDC_FAIL_BASE_TO_ALPACA =
  'Base to Alpaca: the bot accepts this only while the vault withdrawal is unrecorded, ' +
  'and it does not check the chain. First confirm on Base that the bot wallet made no ' +
  "OperatorWithdraw on the inventory after the transfer's from_block, and no WithdrawV2 " +
  'on the orderbook either (a withdrawal sent before the inventory migration). Only a ' +
  'USDC withdrawal from the cash vault counts: its vaultId equals the cash vault_id in ' +
  'the bot config, and the bot wallet is the OperatorWithdraw operator or the WithdrawV2 ' +
  'sender. A WithdrawV2 with the inventory as sender does not count. A withdraw the ' +
  'network accepted but has not mined is not in the logs yet, so also wait until the ' +
  "transfer's attempt timeout has passed and confirm the wallet has no pending " +
  'transaction (no pending withdraw4, pending nonce equals latest nonce on more than one ' +
  'RPC provider, and the explorer shows no queued transaction from the wallet). A queued ' +
  'transaction waits behind a nonce gap: with the bot stopped, fill each empty nonce ' +
  'below it, in order, with a self-transfer as below, after making sure no send the bot ' +
  'signed and keeps holds that nonce, then repeat the checks. These checks cannot prove ' +
  'that nothing is pending. If a withdrawal landed or you are not certain, run ' +
  'resume-usdc instead: it adopts a withdrawal of the full amount, and any other amount ' +
  'ends the transfer in WithdrawalFailed, so move that USDC from the bot wallet back to ' +
  'the cash vault by hand. If nothing landed, the resume keeps redriving: repeat the ' +
  'checks, and once every check is clean, take the next step. If none landed, close the ' +
  'nonce before you fail the transfer: stop the bot, check again that the wallet has no ' +
  'pending or queued transaction, make sure no send the bot signed and keeps holds that ' +
  'nonce (if one does, start the bot so it rebroadcasts the send instead), send a 0-value ' +
  'transfer with no calldata from the bot wallet to itself at the latest nonce, with ' +
  'maxFeePerGas and maxPriorityFeePerGas well above the market fee, wait for its required ' +
  'confirmations, and check the withdrawal logs again. The self-transfer closes only ' +
  'that nonce. If a withdrawal mined instead, a transaction is pending or queued, or you ' +
  'cannot tell, start the bot and run resume-usdc, and do not fail the transfer. ' +
  'Otherwise run the offline stox fail-usdc-transfer, or this command after you restart ' +
  'the bot. If a withdrawal for this transfer mines later anyway, move its USDC from the ' +
  'bot wallet back to the cash vault by hand. While a recorded withdrawal is still ' +
  'confirming, run resume-usdc. Once it has confirmed the bot refuses: do every check ' +
  'and the nonce close on Base in docs/cli-ops.md, "Clearing a pre-burn guard latch". If ' +
  'a burn landed, something is pending or queued, or you are not certain, start the bot ' +
  'and run resume-usdc, and do not fail the transfer. Otherwise run the offline stox ' +
  'fail-usdc-transfer and move the wallet USDC back by hand. If ' +
  'a burn for this transfer mines later anyway, resume and reconcile refuse the failed ' +
  'transfer. Keep the bot stopped until that USDC is at Alpaca: the offline commands send ' +
  'from the bot wallet and replace whatever is pending at their nonce, so first run the ' +
  'pending, queued and kept-send checks on Ethereum as docs/cli-ops.md describes, and let ' +
  'any kept send mine. Mint it with stox ' +
  "cctp complete-mint --burn-tx <burn> --source-chain base (it adopts a relayer's mint; " +
  'do not mint by hand, since the MessageSent log holds a placeholder nonce). Then send ' +
  'the amount received that complete-mint printed, divided by 1,000,000 (it prints USDC ' +
  'base units), to Alpaca with stox alpaca-deposit -a <amount>, and do not move that USDC ' +
  'back to the vault. Once Alpaca credits it, convert ' +
  'it with stox alpaca-convert -d to-usd -a <amount>, as the bot would have.';

const USDC_BRIDGING_BASE_TO_ALPACA =
  ' If the burn keeps failing, the running bot refuses fail-usdc-transfer here: see ' +
  'fail-usdc-transfer in the CLI recovery guide for the offline path.';

const USDC_CONVERTING_ALPACA_TO_BASE =
  ' Alpaca to Base: this status covers two bot states. If the bot recorded the ' +
  'conversion as complete, this resume continues with the Alpaca withdrawal. If not, the ' +
  'bot cannot re-drive the USD to USDC conversion (it did not store the broker order ' +
  'id), so this resume fails the transfer (ConversionFailed) and releases the guard, ' +
  'without checking Alpaca. So first confirm at Alpaca that no USD to USDC order for ' +
  'this transfer is still open (it is filled, cancelled or rejected), above all after a ' +
  'conversion outcome unresolved alert; if one is open, cancel it or wait for it. Do not ' +
  'move USDC by hand before you run the resume. If it ends in ConversionFailed, settle ' +
  'any converted USDC by hand at Alpaca (reconcile-usdc does not apply). A later failure ' +
  'has its own recovery.';

// usdcResumeNote in transfer.ts: the extra resume text for a bridge's status
// and direction.
const usdcResumeNote = (status, direction) => {
  if (direction === 'base_to_alpaca' && status === 'bridging') return USDC_BRIDGING_BASE_TO_ALPACA;
  if (direction !== 'base_to_alpaca' && status === 'converting') return USDC_CONVERTING_ALPACA_TO_BASE;
  return '';
};

// usdcFailCheck in transfer.ts: the check before fail-usdc-transfer, or null
// where the running bot always refuses it.
const usdcFailCheck = (status, direction) => {
  if (direction === 'alpaca_to_base') {
    return status === 'withdrawing' || status === 'bridging' ? USDC_FAIL_ALPACA_TO_BASE : null;
  }
  if (direction === 'base_to_alpaca') return status === 'withdrawing' ? USDC_FAIL_BASE_TO_ALPACA : null;
  return status === 'withdrawing' || status === 'bridging'
