// The body of Grafana's /api/ds/query for the row's lines.
const rowEventsRequest = ({ datasource, eventsFilter, project, id, first, newest }) => ({
  queries: [
    {
      refId: 'row-events',
      datasource,
      projectId: project,
      queryType: 'logs',
      queryText: rowEventsFilter(eventsFilter, id),
      maxDataPoints: ROW_EVENTS_LIMIT,
