const mergeEntries = (board, fetched) => {
  const seen = new Set();
  return [...board, ...fetched].filter((entry) => {
    if (!entry.event_id) return true;
    if (seen.has(entry.event_id)) return false;
    seen.add(entry.event_id);
    return true;
  });
};


